def detect_too_critical_v2(code: str) -> str:
    try:
        tree = ast.parse(code)
        critical = []
        for node in ast.walk(tree):
            if isinstance(node, ast.Assign):
                for target in node.targets:
                    if isinstance(target, ast.Name) and target.id == "too_critical":
                        critical.append(f"Assignment to 'too_critical' at {ast.get_source_segment(code, node)}")
            elif isinstance(node, ast.If):
                for test in [node.test] + [n.test for n in ast.walk(node) if isinstance(n, ast.If)]:
                    if isinstance(test, ast.Name) and test.id == "too_critical":
                        critical.append(f"Condition on 'too_critical' at {ast.get_source_segment(code, node)}")
        return f"Too critical flags: {len(critical)} (see above)" if critical else "No too_critical flags found"
    except:
        return "Could not parse code for too_critical analysis"
